async request(
  operation: HostCustodyCall['operation'], build: (deadlineMs: number) => HostCustodyCall, deadline?: number,
  onRefusal?: (reason: 'refused' | 'unknown' | 'result-mismatch') => void
): Promise<HostCustodyResult> {
  const reply = await this.connected().requestWhenReady(operation, build, deadline);
  if (reply.status !== 'completed' || reply.value.operation !== operation) {
    try { onRefusal?.(reply.status === 'completed' ? 'result-mismatch' : reply.status); } catch { /* Passive only. */ }
    unavailable();
  }
  return reply.value;
}

private readonly refuse = (reason: LaunchRefusal, deadlineExpired: true | null = null): void => {
  if (this.refusalObserved) return;
  this.refusalObserved = true;
  if (refusalChannel.hasSubscribers) try {
    refusalChannel.publish({ kind: 'native', capability: this.key, phase: this.phase, reason,
      dispatched: this.dispatched, staged: this.staged, rootCaptured: this.rootIdentity !== undefined, deadlineExpired });
  } catch { /* The original refusal remains authoritative. */ }
};
private assertInput(preparing = false): void {
  if (this.sealed) { if (preparing) this.refuse('sealed'); unavailable(); }
  let current: boolean;
  try { current = this.current(); } catch (error) { if (preparing) this.refuse('current-threw'); throw error; }
  if (!current) { if (preparing) this.refuse('current-false'); unavailable(); }
  if (preparing && performance.now() >= this.deadline) { this.refuse('launch-deadline', true); unavailable(); }
}

async prepare(): Promise<Preparation> {
  this.phase = 'prepare';
  try {
    this.assertInput(true);
    if (!this.staged || this.rootIdentity) unavailable();
    const prepared = await this.source.request(
      'prepare', () => {
        this.assertInput(true);
        return { operation: 'prepare', capability: this.key };
      }, this.deadline, this.refuse
    );
    if (prepared.operation !== 'prepare') { this.refuse('result-mismatch'); unavailable(); }
    this.rootIdentity = Object.freeze({ ...prepared.root });
    if (this.stateHint) void this.observeState();
    this.phase = 'post-prepare'; this.assertInput(true);
    return { kind: 'prepared', process: this };
  } catch {
    return this.failed();
  }
}

async resume(expectedOwner: ProcessOwner, installOwner: () => Promise<void>): Promise<void> {
  this.phase = 'resume';
  if (!sameOwner(expectedOwner, this.owner) || !this.rootIdentity || this.resumed) {
    this.refuse('preparation-failed'); unavailable();
  }
  this.assertInput(true);
  try { await installOwner(); } catch (error) { this.refuse('preparation-failed'); throw error; }
  this.assertInput(true);
  const result = await this.source.request(
    'resume', () => {
      this.assertInput(true);
      return { operation: 'resume', capability: this.key };
    }, this.deadline, this.refuse
  );
  if (result.operation !== 'resume') { this.refuse('result-mismatch'); unavailable(); }
  this.assertInput(true);
  this.resumed = true;
  this.readable('state');
}

/** Only references wait here. The builder receives the fixed deadline after queueing and timeout clamping. */
requestWhenReady(
  operation: HostCustodyCall['operation'],
  build: (deadlineMs: number) => HostCustodyCall,
  deadlineMs?: number
): Promise<HostCustodyReply> {
  const now = performance.now();
  const deadline = Math.min(deadlineMs ?? now + this.options.timeoutMs, now + this.options.timeoutMs);
  const queued = this.admissions.control.length + this.admissions.work.length;
  if (this.sealed || !this.binding || this.next > MAX_SEQUENCE ||
    (this.inputSealed && !hostCustodyCleanup({ operation })) ||
    !Number.isFinite(deadline) || deadline <= now || queued + this.pending.size >= 6 * 256)
    return Promise.resolve({ status: 'refused' });
  const lane = hostCustodyControl({ operation }) ? this.admissions.control : this.admissions.work;
  return new Promise((resolve) => {
    let settled = false;
    const admission: NativeAdmission = {
      operation, build, deadline,
      timer: setTimeout(() => admission.finish({ status: 'refused' }), deadline - now),
      finish: (reply) => {
        if (settled) return;
        settled = true;
        clearTimeout(admission.timer);
        const index = lane.indexOf(admission);
        if (index >= 0) lane.splice(index, 1);
        resolve(reply);
        this.resumeAdmission();
      },
    };
    lane.push(admission);
    this.resumeAdmission();
  });
}

/** Called when the original output write frees shared bytes, or a reply frees a request slot. */
resumeAdmission(): void {
  if (this.admitting || this.sealed) return;
  this.admitting = true;
  try {
    for (;;) {
      const lane = this.admissions.control.length ? this.admissions.control : this.admissions.work;
      const admission = lane[0];
      if (!admission) return;
      const control = hostCustodyControl(admission);
      const capacity = this.options.limits.maxPendingRequests -
        (control ? 0 : this.options.limits.reservedControlRequests);
      if (admission.deadline <= performance.now() ||
        (this.inputSealed && !hostCustodyCleanup(admission))) {
        admission.finish({ status: 'refused' });
        continue;
      }
      if (this.pending.size >= capacity || this.options.canSend?.(control) === false) return;
      lane.shift();
      clearTimeout(admission.timer);
      let parsed: ReturnType<typeof callSchema.safeParse>;
      try { parsed = callSchema.safeParse(admission.build(admission.deadline)); }
      catch { admission.finish({ status: 'refused' }); continue; }
      if (!parsed.success || parsed.data.operation !== admission.operation) {
        admission.finish({ status: 'refused' }); continue;
      }
      // dispatch rechecks the original deadline after the lazy builder, without extending it.
      void this.dispatch(parsed.data, admission.deadline).then(admission.finish);
    }
  } finally { this.admitting = false; }
}

private dispatch(call: HostCustodyCall, deadline: number): Promise<HostCustodyReply> {
  if (this.sealed || !this.binding || this.next > MAX_SEQUENCE ||
    (this.inputSealed && !hostCustodyCleanup(call)))
    return Promise.resolve({ status: 'refused' });
  const remaining = Math.floor(deadline - performance.now());
  if (!Number.isFinite(remaining) || remaining <= 0) return Promise.resolve({ status: 'refused' });
  const control = hostCustodyControl(call);
  if (call.operation === 'read' && [...this.pending.values()].some(({ call: other }) =>
    other.operation === 'read' && other.capability === call.capability && other.stream === call.stream))
    return Promise.resolve({ status: 'refused' });
  const id = `custody:${this.binding.hostIncarnation}:${control ? 'control' : 'work'}:${this.next++}`;
  const hintKey = hostCustodyHintKey(call);
  const admittedHint = hintKey ? this.hints.get(hintKey) : undefined;
  const wireCall = call.operation === 'allocate' ? (() => {
    const { runtimeSourceOrigin, ...original } = call;
    return runtimeSourceOrigin === undefined ? original : { ...original, runtimeSourceOrigin };
  })() : call;
  const frame: RpcRequest = {
    jsonrpc: '2.0', id, method: HOST_CUSTODY_METHOD, params: { binding: this.binding, call: wireCall, remainingMs: remaining },
  };
  return new Promise((resolve) => {
    let returned = false;
    const settle = (reply: HostCustodyReply) => {
      if (!returned) { returned = true; resolve(reply); }
    };
    const finish = (reply: HostCustodyReply) => {
      const pending = this.pending.get(id);
      if (!pending) return;
      clearTimeout(pending.timer);
      this.pending.delete(id);
      if (reply.status === 'completed' && hintKey) {
        const current = this.hints.get(hintKey);
        if (current === admittedHint) this.hints.delete(hintKey);
        else if (current) for (const observer of this.observers) observer(current);
      }
      if (reply.status === 'completed' && reply.value.operation === 'release' && reply.value.state === 'released')
        for (const key of this.hints.keys()) if (key.startsWith(`${call.capability}:`)) this.hints.delete(key);
      settle(reply);
      this.resumeAdmission();
    };
    // A caller timeout is not an ACK: retain its slot, ID and marker until the original reply.
    const expire = () => settle({ status: 'unknown' });
    const timer = setTimeout(expire, remaining);
    this.pending.set(id, { call, finish, timer });
    try { if (!this.options.send(frame, control)) finish({ status: 'refused' }); }
    catch { expire(); }
  });

/** Returns false only for an ordinary Host request. Malformed private frames fail the transport. */
receive(value: unknown, frameBytes: number): boolean {
  const candidate = value as { id?: unknown; method?: unknown } | null;
  if (candidate?.method === HOST_CUSTODY_READY_METHOD) {
    const ready = readySchema.safeParse(value);
    if (frameBytes > HOST_CUSTODY_FRAME_BYTES || !ready.success)
      throw new Error('Invalid private custody readiness');
    if (
      !this.sealed &&
      this.binding &&
      sameHostCustodyBinding(this.binding, ready.data.params.binding)
    ) {
      const hint = ready.data.params.hint;
      const key = `${hint.capability}:${hint.stream}`;
      const previous = this.hints.get(key);
      if (!previous) {
        if (this.hints.size >= HOST_CUSTODY_MAX_ALLOCATIONS * 3)
          throw new Error('Private custody readiness capacity');
      }
      // A pending read can acknowledge only the marker it actually observed.
      this.hints.set(key, hint);
      if (!previous) for (const observer of this.observers) observer(hint);
    }
    return true;
  }
  if (typeof candidate?.id !== 'string' || !candidate.id.startsWith('custody:')) return false;
  const pending = this.pending.get(candidate.id);
  if (!pending) return true; // Old, retired or timed-out reply cannot finish a different request/epoch.
  const response = responseSchema.safeParse(value);
  if (
    frameBytes > HOST_CUSTODY_FRAME_BYTES ||
    !response.success ||
    !this.binding ||
    !sameHostCustodyBinding(this.binding, response.data.result.binding)
  )
    throw new Error('Invalid private custody response');
  const reply = response.data.result.reply;
  if (reply.status === 'completed') validateHostCustodyResult(pending.call, reply.value);
  pending.finish(reply);
  return true;
}

seal(): void {
  if (this.sealed) return;
  this.sealed = true;
  for (const pending of this.pending.values()) pending.finish({ status: 'unknown' });
  for (const admission of [...this.admissions.control, ...this.admissions.work])
    admission.finish({ status: 'refused' });
  this.observers.clear();
  this.hints.clear();
}

sealInput(): void {
  this.inputSealed = true;
  for (const admission of [...this.admissions.control, ...this.admissions.work])
    if (!hostCustodyCleanup(admission)) admission.finish({ status: 'refused' });
  this.resumeAdmission();

export function inspectMemberModelReadiness(options: {
  management?: Pick<ProviderManagementCoordinator, 'probes' | 'readinessTarget'>;
  launch: TeamLaunchOwner; entry: MemberEntry; assertCurrent(): void;
  hostIncarnation: string; phase?: 'preclaim' | 'allocation';
}): { assertCurrent(): void; consumerId: string; kind: 'preparation' | 'continuation' | 'initial';
  reference?: ModelReadinessReference; assertReadinessCredential?(scopeDigest: string): void } {
  const { entry, launch } = options;
  const selected = { binding: entry.binding, configRevision: entry.profile.configRevision,
    configurationDigest: runtimeDigest(entry.profile) };
  const original = launch.readModelReadiness(selected);
  if (original.consumer.initialProfile) return inspectInitialRuntimeModelAdmission({ ...options,
    phase: options.phase ?? 'preclaim' });
  const observedAccount: { value?: NonNullable<ReturnType<typeof captureOpenCodeProbeAccount>> } = {};
  let refusalObserved = false;
  const currentCalls = { count: 0, totalMs: 0, maxMs: 0, lastMs: null as number | null, truncated: false };
  const current = () => {
    let phase = 'initial-authority', reason: 'held' | 'threw' = 'threw';
    let cutoff: number | null = null, observedAt: number | null = null;
    let started: number | undefined, failed = false;
    try {
      if (readinessRefusal.hasSubscribers && !refusalObserved) {
        currentCalls.lastMs = null;
        if (currentCalls.count < 4096) { currentCalls.count++; started = performance.now(); }
        else currentCalls.truncated = true;
      }
    } catch { currentCalls.truncated = true; }
    try {
      options.assertCurrent(); phase = 'read-consumer';
      const current = launch.readModelReadiness(selected), consumer = current.consumer;
      phase = 'identity';
      if (consumer.consumerId !== original.consumer.consumerId ||
          consumer.baseConfigurationDigest !== runtimeDigest(entry.baseProfile)) { reason = 'held'; held(); }
      phase = 'continuation';
      if (consumer.continuation) {
        const restore = entry.selection?.restore;
        if (!restore || restore.reference !== consumer.continuation.reference ||
            runtimeDigest(restore.sourceBinding) !== runtimeDigest(consumer.continuation.sourceBinding)) { reason = 'held'; held(); }
        return;
      }
      phase = 'requirements';
      if (!options.management || !current.reference || consumer.cutoff === undefined) { reason = 'held'; held(); }
      phase = 'cutoff';
      if ((observedAt = Date.now()) >= (cutoff = consumer.cutoff)) { reason = 'held'; held(); }
      phase = 'reference';
      const observed = readPreparedModelReference({ management: options.management, profile: entry.profile,
        commandId: current.reference.commandId, context: current.reference.context,
        ...(current.reference.purpose === 'ordinary' ? { kind: 'native' as const } : {}),
        observeAccount: value => { if (value) observedAccount.value = value; else delete observedAccount.value; },
        isCurrent: () => { try { options.assertCurrent(); return true; } catch { return false; } } }, true);
      phase = 'equality';
      if (runtimeDigest(observed) !== runtimeDigest(current.reference)) { reason = 'held'; held(); }
      phase = 'final-authority'; options.assertCurrent();
    } catch (error) {
      failed = true; throw error;
    } finally {
      if (started !== undefined) try {
        const elapsed = Math.round(performance.now() - started);
        if (!Number.isSafeInteger(elapsed) || elapsed < 0 || !Number.isSafeInteger(currentCalls.totalMs + elapsed))
          currentCalls.truncated = true;
        else { currentCalls.totalMs += elapsed; currentCalls.maxMs = Math.max(currentCalls.maxMs, elapsed); currentCalls.lastMs = elapsed; }
      } catch { currentCalls.truncated = true; }
      if (failed && !refusalObserved) {
        refusalObserved = true;
        try { if (readinessRefusal.hasSubscribers) readinessRefusal.publish({
          kind: 'consumer', actionDigest: runtimeDigest(original.consumer.actionId),
          groupDigest: runtimeDigest({ commandDigest: runtimeDigest(original.consumer.groupCommandId ?? null),
            contextDigest: runtimeDigest(original.reference?.context ?? null) }), bindingDigest: managementDigest(selected.binding),
          consumerId: original.consumer.consumerId, phase, reason, cutoff, observedAt, currentCalls: { ...currentCalls },
        }); } catch { /* Original TEST subscriber handles its own errors; preserve this refusal. */ }
      }
    }
  };
  current();
  return { assertCurrent: current, consumerId: original.consumer.consumerId,
    kind: original.consumer.continuation ? 'continuation' : 'preparation',
    ...(original.reference ? { reference: original.reference } : {}),
    ...(!original.consumer.continuation && observedAccount.value?.nativeCredentialScopeDigest !== undefined ? {
      assertReadinessCredential(scopeDigest: string) {
        current();
        const account = observedAccount.value;
        if (!account || !account.isCurrent() || account.nativeCredentialScopeDigest !== scopeDigest) held();
      },
    } : {}) };
}

